<?php
// Treks v2.0.20: Chapter III-a "The Humming Deep" (draft title). Run on an installed copy: php tests/trek_ch3.php GAME_DIR (treks.sh does).
// Map, spots, reachability, the chapter gate (trek_chapters_open), Wren (recruit, join card, +20 friendship, Bloom crew moment), milestones once-only
// (also after an admin reset), the Old Gneiss script, the Ch II -> III carry-over (levels, tactics, kits, an extra st.kn key), and the 35-party boss sim + zone sims.
$GAME = $argv[1];
$_SERVER['SCRIPT_NAME'] = '/trek.php';
require $GAME . '/includes/bootstrap.php';
require_once $GAME . '/includes/trek.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
$fails = 0;
set_exception_handler(function (Throwable $e) { if (db()->inTransaction()) db()->rollBack(); echo '  EXCEPTION ' . get_class($e) . ': ' . $e->getMessage() . ' @ ' . basename($e->getFile()) . ':' . $e->getLine() . "\n"; exit(1); });
function ok(string $what, bool $cond, string $extra = ''): void { global $fails; echo ($cond ? '  ok   ' : '  FAIL ') . $what . ($cond ? '' : "  $extra") . "\n"; if (!$cond) $fails++; }
$uid = (int)q_val("SELECT id FROM users WHERE username = 'sprout'");
$tx = fn(callable $f, bool $need = true, ?int $ch = null) => trek_tx($uid, $f, $need, $ch);
$run = fn(?int $ch = null) => trek_load(trek_run_row($uid, $ch));
$mainXp = fn() => (int)q_val('SELECT xp FROM users WHERE id = ?', [$uid]);
set_setting('trek_open', '1'); set_setting('trek_event_pct', '0'); set_setting('trek_enc_percent', '0'); set_setting('trek_petals_daily', '150'); set_setting('trek_entry_energy', '10');
foreach (['trek_ms_ch3_wren' => 450, 'trek_ms_ch3_gneiss' => 1100, 'trek_ms_ch3a_end' => 900] as $k => $v) set_setting($k, (string)$v);
set_setting('trek_chapters_open', '2'); setting('__reload__');
q('UPDATE creature_drops SET chance = 0 WHERE 1 = 1');

echo "== data: chapter, map, spots, creatures\n";
ok('Chapter III exists, zones t u v w x, milestones ch3_wren ch3_gneiss ch3a_end, no finish row (III-b), no Chapter IV', trek_chapter_exists(3) && array_keys(trek_chapter(3)['zones']) === ['t', 'u', 'v', 'w', 'x'] && array_keys(trek_milestones(3)) === ['ch3_wren', 'ch3_gneiss', 'ch3a_end'] && !trek_chapter_exists(4) && trek_next_chapter(3) === null);
$map = trek_map(3);
ok('the map is 40 x 50 with a zone row for each', $map['w'] === 40 && $map['h'] === 50 && count($map['z']) === 50, $map['w'] . 'x' . $map['h']);
$n = 0; for ($y = 0; $y < $map['h']; $y++) for ($x = 0; $x < $map['w']; $x++) { $c = trek_tile(3, $x, $y); if ($c !== '#' && $c !== '^' && $c !== ' ' && $c !== '*') $n++; }
ok('about 520 walkable tiles (480-560)', $n >= 480 && $n <= 560, (string)$n);
$sp = trek_spots(3);
ok('12 spots, every symbol sits on its own tile', count($sp) === 12 && !array_filter($sp, fn($s) => trek_tile(3, $s['x'], $s['y']) !== $s['data']['sym'] && $s['type'] !== 'start'));
$types = array_count_values(array_column($sp, 'type'));
ok('1 camp, 1 oldcamp, 1 rest, 1 riddle, 1 find (Wayfinder nook), 1 cart, 1 miniboss, 1 recruit, 2 gates', ($types['camp'] ?? 0) === 1 && ($types['oldcamp'] ?? 0) === 1 && ($types['rest'] ?? 0) === 1 && ($types['riddle'] ?? 0) === 1 && ($types['find'] ?? 0) === 1 && ($types['cart'] ?? 0) === 1 && ($types['miniboss'] ?? 0) === 1 && ($types['recruit'] ?? 0) === 1 && ($types['gate'] ?? 0) === 2, json_encode($types));
$cr = ['shale-slater' => 20, 'quartz-snail' => 21, 'pale-olm' => 21, 'echo-bat' => 22, 'gravel-centipede' => 23];
$bad = []; foreach ($cr as $s => $lv) { $c = trek_creature($s); if (!$c || (int)$c['level'] !== $lv || !is_file($GAME . '/assets/img/ph/creature-' . $s . '.svg')) $bad[] = $s; }
ok('five new creatures at Lv20-23 with placeholder art, plus the boss Old Gneiss', !$bad && trek_creature('old-gneiss') && is_file($GAME . '/assets/img/ph/creature-old-gneiss.svg'), implode(',', $bad));
ok('pools t u v w x exist and sit in chapter 3; Chapter I and II pools untouched', trek_zone_pool('t', 3) && trek_zone_pool('x', 3) && trek_zone_pool('g', 1) && trek_zone_pool('j', 2));
ok('Wren is in the crew list: Bloomcaller, chapter 3, lore 3, her npc exists', (trek_crew()['wren']['calling'] ?? '') === 'bloomcaller' && (int)trek_crew()['wren']['chapter'] === 3 && (int)q_val('SELECT COUNT(*) FROM npcs WHERE slug = ?', ['wren-thimblewick']) === 1);
ok('book entries: deeprock and gneiss belong to chapter 3', (TREK_BOOK_CH['deeprock'] ?? 0) === 3 && (TREK_BOOK_CH['gneiss'] ?? 0) === 3);

echo "== the chapter gate (trek_chapters_open)\n";
foreach (['trek_flags', 'trek_pack', 'trek_party', 'trek_recruits'] as $t) q("DELETE FROM $t WHERE run_id IN (SELECT id FROM trek_runs WHERE user_id = ?)", [$uid]);
q('DELETE FROM trek_runs WHERE user_id = ?', [$uid]); q('DELETE FROM trek_ms WHERE user_id = ?', [$uid]);
q('UPDATE users SET level = 16, energy = 100, coins = 1000, calling = NULL, role = ?, trek_ch = 1, trek_pet_day = NULL, trek_pet_today = 0 WHERE id = ?', ['player', $uid]);
$tx(fn(&$run, $u) => trek_enter($run, $u), false);
$tx(function (&$run, $u) { foreach (['burdock', 'zinnia', 'bracken'] as $k) trek_recruit_crew($run, $u, $k); $run['st']['tl']['gnome'] = [15, 5]; $run['st']['tl']['burdock'] = [14, 0]; $run['st']['tl']['zinnia'] = [14, 3]; $run['st']['tl']['bracken'] = [13, 0]; $run['st']['tac']['burdock'] = ['rule' => 'always']; $run['campkits'] = 2; trek_complete_chapter($run, $u); trek_hub_arrive($run, $u); return [true, '']; });
$r = $tx(fn(&$run, $u) => trek_godown($run, $u));
ok('Chapter I -> II still works at the default setting 2', $r[0] === true && trek_active_ch($uid) === 2, json_encode($r));
$tx(function (&$run, $u) { $run['st']['tl']['gnome'] = [16, 40]; $run['st']['tl']['sorrel'] = [15, 0]; $run['campkits'] = 3; $run['st']['kn'] = ['pts' => 2]; trek_complete_chapter($run, $u); trek_hub_arrive($run, $u); return [true, '']; });
$R2 = $run(2);
$e0 = (int)q_val('SELECT energy FROM users WHERE id = ?', [$uid]);
$r = $tx(fn(&$run, $u) => trek_godown($run, $u));
ok('a player at trek_chapters_open = 2 cannot go down to III: "coming soon", no energy spent, no run made, still in the hub of II', $r[0] === false && str_contains((string)$r[1], 'coming soon') && (int)q_val('SELECT energy FROM users WHERE id = ?', [$uid]) === $e0 && trek_run_row($uid, 3) === null && trek_active_ch($uid) === 2, json_encode($r));
$page = (string)file_get_contents($GAME . '/trek.php');
ok('the hub\'s Go down box uses the same check (page source: a closed chapter nulls $next, so only the coming-soon text shows)', str_contains($page, '!trek_chapter_open($next, $u)) $next = null;'));
ok('the check itself: players need the setting, admins bypass', !trek_chapter_open(3, ['role' => 'player']) && trek_chapter_open(2, ['role' => 'player']) && trek_chapter_open(3, ['role' => 'admin']));
set_setting('trek_chapters_open', '3'); setting('__reload__');
ok('with the setting at 3 a player may go', trek_chapter_open(3, ['role' => 'player']));
set_setting('trek_chapters_open', '2'); setting('__reload__');
q('UPDATE users SET role = ? WHERE id = ?', ['admin', $uid]);
$e0 = (int)q_val('SELECT energy FROM users WHERE id = ?', [$uid]);
$xpKit = $run(2);
$r = $tx(fn(&$run, $u) => trek_godown($run, $u));
ok('an admin goes down at setting 2, paying the entry energy once', $r[0] === true && trek_active_ch($uid) === 3 && (int)q_val('SELECT energy FROM users WHERE id = ?', [$uid]) === $e0 - 10, json_encode($r));
$R3 = $run(3);
q('UPDATE users SET role = ? WHERE id = ?', ['player', $uid]);
$sp3 = trek_spots(3); $st = $sp3['start'];
ok('carry-over II -> III: start tile, trek levels, tactics, Camp Kits and the party come along; flags, pack and fight do not', (int)$R3['chapter'] === 3 && [$R3['x'], $R3['y']] === [$st['x'], $st['y']] && $R3['st']['tl'] === $xpKit['st']['tl'] && ($R3['st']['tac']['burdock']['rule'] ?? '') === 'always' && (int)$R3['campkits'] === (int)$xpKit['campkits'] && $R3['flags'] === [] && !trek_pack_rows((int)$R3['id']) && $R3['fi'] === null && count($R3['party']) === count($xpKit['party']), json_encode([$R3['st']['tl'], $xpKit['st']['tl']]));
ok('II -> III: a gnome level 16 is kept; recruits are kept', ($R3['st']['tl']['gnome'][0] ?? 0) === 16 && in_array('sorrel', trek_recruits((int)$R3['id']), true) || in_array('burdock', trek_recruits((int)$R3['id']), true));
ok('an extra st.kn key (the knacks builder) does not break a new run, and it is not carried blindly into a broken state', is_array($R3['st']));
ok('Chapter II\'s run is unchanged by going down', trek_run_done($run(2)) && ($run(2)['st']['kn']['pts'] ?? null) === 2);
set_setting('trek_chapters_open', '2'); setting('__reload__');
$u3 = q_one('SELECT * FROM users WHERE id = ?', [$uid]);
$still = $tx(fn(&$run, $u) => [(int)$run['inside'] === 1 && (int)$run['chapter'] === 3, ''], true, 3)[0];
ok('a player already inside Chapter III stays and keeps playing when the setting is lowered (the run loads, nothing kicks them out)', trek_active_ch($uid) === 3 && $still && !trek_chapter_open(3, $u3));

echo "== reachability, route length\n";
$tx(function (&$run, $u) { $run['sn'] = str_repeat("\xff", strlen($run['sn'])); return [true, '']; }, true, 3);
$at = fn(string $code) => $tx(function (&$run, $u) use ($code) { $s = trek_spots(3)[$code]; $run['x'] = $s['x']; $run['y'] = $s['y']; $run['fatigue'] = 0; return [true, '']; }, true, 3);
$pathLen = fn(string $code) => $tx(function (&$run, $u) use ($code) { $s = trek_spots(3)[$code]; return [count(trek_path($run, $s['x'], $s['y'])), '']; }, true, 3)[0];
$flag = fn(string $f) => !empty($run(3)['flags'][$f]);
$setFlag = fn(string $f) => $tx(function (&$run, $u) use ($f) { trek_flag_set($run, $f); return [true, '']; }, true, 3);
$at('start');
$miss = []; foreach (['orecart', 'camp', 'chalk', 'bench', 'knock', 'knockgate'] as $c) if (!$pathLen($c)) $miss[] = $c;
ok('start -> cart, camp, chalk, bench, riddle door, tapping door are all reachable without any key', !$miss, implode(',', $miss));
ok('beyond the Tapping Door: Wren, the Warm Ledge, Old Gneiss and the Still Gate are NOT reachable while the door is shut', !$pathLen('wren') && !$pathLen('gneiss') && !$pathLen('stillgate'));
$setFlag('knock_open');
$miss = []; foreach (['wren', 'oldwarm', 'gneiss'] as $c) if (!$pathLen($c)) $miss[] = $c;
ok('with the riddle door open: Wren, the Warm Ledge and Old Gneiss are reachable', !$miss, implode(',', $miss));
$nook = $sp3['nookA'];
ok('the Wayfinder nook is hidden behind loose clay: no way in without a Wayfinder in the party', !$pathLen('nookA'));
$wfLen = $tx(function (&$run, $u) { trek_party_stats($run, $u); $run['wf'] = true; $s = trek_spots(3)['nookA']; return [count(trek_path($run, $s['x'], $s['y'])), '']; }, true, 3)[0];
ok('...and a Wayfinder pushes through', $wfLen > 0);
$total = 0; $prev = 'start';
foreach (['orecart', 'camp', 'chalk', 'knock', 'wren', 'gneiss'] as $c) { $at($prev); $total += $pathLen($c); $prev = $c; }
$at('gneiss'); $total += $pathLen('stillgate') ?: 0;
ok('the main route is 150-260 steps (about 200)', $total >= 150 && $total <= 260, (string)$total);

echo "== the Knock Door: riddle, 2 tries, Seedkeeper\n";
$tx(function (&$run, $u) { q('DELETE FROM trek_flags WHERE run_id = ? AND flag = ?', [(int)$run['id'], 'knock_open']); unset($run['flags']['knock_open']); return [true, '']; }, true, 3);
$at('knock');
$right = (int)($sp3['knock']['data']['right']);
$wrong = $right === 1 ? 2 : 1;
$tx(fn(&$run, $u) => trek_act_riddle($run, $u, $wrong), true, 3);
ok('a wrong answer: still shut, 1 try used', !$flag('knock_open') && (int)($run(3)['st']['tries_knock'] ?? 0) === 1);
$tx(fn(&$run, $u) => trek_act_riddle($run, $u, $wrong), true, 3);
ok('the 2nd wrong answer: the door gives way (failopen) but is NOT counted as solved', $flag('knock_open') && !$flag('knock_solved'));
$tx(function (&$run, $u) { q('DELETE FROM trek_flags WHERE run_id = ? AND flag IN (?, ?)', [(int)$run['id'], 'knock_open', 'knock_solved']); unset($run['flags']['knock_open'], $run['flags']['knock_solved']); $run['st']['tries_knock'] = 0; return [true, '']; }, true, 3);
$tx(fn(&$run, $u) => trek_act_riddle($run, $u, $right), true, 3);
ok('the right answer opens it AND counts as solved', $flag('knock_open') && $flag('knock_solved'));

echo "== side stops\n";
$at('orecart');
$k0 = (int)$run(3)['campkits'];
$r = $tx(fn(&$run, $u) => trek_act_cart($run, $u, 'work'), true, 3);
ok('the ore cart is a once-only stop', $flag('cart_done') && ($tx(fn(&$run, $u) => trek_act_cart($run, $u, 'work'), true, 3)[0] === false));
$at('bench');
$tx(function (&$run, $u) { $run['fatigue'] = 60; return [true, '']; }, true, 3);
$tx(fn(&$run, $u) => trek_act_rest($run, $u), true, 3);
ok('the Quiet Bench is one free rest', $flag('rest_used') && (int)$run(3)['fatigue'] === 10 && $tx(fn(&$run, $u) => trek_act_rest($run, $u), true, 3)[0] === false);
$at('nookA');
$tx(fn(&$run, $u) => trek_act_hidden($run, $u), true, 3);
ok('the Wayfinder nook pays once (flag nookA_found)', $flag('nookA_found') && $tx(fn(&$run, $u) => trek_act_hidden($run, $u), true, 3)[0] === false);

echo "== Wren Thimblewick: recruit, join card, +20 friendship, Bloom crew moment, milestone once-only\n";
$npcId = (int)q_val('SELECT id FROM npcs WHERE slug = ?', ['wren-thimblewick']);
q('DELETE FROM npc_friends WHERE npc_id = ? AND user_id = ?', [$npcId, $uid]);
unset($_SESSION['trek_scene_auto']);
$at('wren');
$xp0 = $mainXp();
$r = $tx(fn(&$run, $u) => trek_act_recruit($run, $u), true, 3);
$R = $run(3);
ok('Wren joins: flag, recruit row', $r[0] === true && $flag('freed_wren') && in_array('wren', trek_recruits((int)$R['id']), true));
ok('friendship with Wren is at least 20', (int)friendship($uid, $npcId)['points'] >= 20);
$items = $_SESSION['trek_scene_auto']['items'] ?? [];
$joins = array_values(array_filter($items, fn($i) => ($i['join'] ?? '') === 'wren'));
ok('the join card is queued for Wren', count($joins) === 1);
$card = trek_scene_joincard($R, q_one('SELECT * FROM users WHERE id = ?', [$uid]), 'wren', (bool)($joins[0]['placed'] ?? false));
ok('the join card has name, Bloomcaller line, trek level, numbers and a bio', $card && $card['name'] === 'Wren' && str_contains($card['sub'], 'Bloomcaller') && str_contains($card['sub'], 'Trek Lv') && $card['stats']['Health'] > 0 && $card['role'] !== '');
$msRow = q_one('SELECT * FROM trek_ms WHERE user_id = ? AND ms_key = ?', [$uid, TREK_KEY . ':ch3_wren']);
ok('ch3_wren paid once, from the setting (max 450 XP), through the milestone only', $msRow && (int)$msRow['xp'] > 0 && (int)$msRow['xp'] <= 450 && $mainXp() >= $xp0 + (int)$msRow['xp'], json_encode($msRow));
$r = $tx(fn(&$run, $u) => trek_act_recruit($run, $u), true, 3);
ok('a second tap does nothing and pays nothing', $r[0] === false && (int)q_val('SELECT COUNT(*) FROM trek_ms WHERE user_id = ? AND ms_key = ?', [$uid, TREK_KEY . ':ch3_wren']) === 1);
$at('camp');
$rp = $tx(function (&$run, $u) { return trek_set_party($run, $u, [1 => 'burdock', 2 => 'zinnia', 3 => 'wren']); }, true, 3);
ok('Wren can be put in the party', ($rp[0] ?? false) === true && in_array('wren', array_column($run(3)['party'], 'crew_key'), true), json_encode($rp));
$tx(function (&$run, $u) { $run['st']['bless'] = 0; $run['st']['cm'] = 'wren'; return [true, '']; }, true, 3);
$r = $tx(fn(&$run, $u) => trek_act_crew($run, $u, 3), true, 3);
ok('Wren\'s crew moment (Bloom) sets st.bless, once', $r[0] === true && (int)($run(3)['st']['bless'] ?? 0) === 1, json_encode($r));
$r = $tx(fn(&$run, $u) => trek_act_crew($run, $u, 3), true, 3);
ok('...and not twice', $r[0] === false);

echo "== Old Gneiss: shown a round ahead, cracks, win pays once\n";
$at('camp');
$tx(function (&$run, $u) { trek_set_party($run, $u, [1 => 'burdock', 2 => 'zinnia', 3 => 'wren']); foreach (trek_party_stats($run, $u) as $sl => $m) $run['party'][$sl]['hp'] = $m['max']; return [true, '']; }, true, 3);
$at('gneiss');
$tx(fn(&$run, $u) => trek_act_challenge($run, $u), true, 3);
$R = $run(3);
ok('the fight starts with the script bound and one foe', $R['fi'] && ($R['fi']['meta']['script'] ?? '') === 'gneiss' && count($R['fi']['foes']) === 1);
[$cur, $next] = trek_boss_moves($R['fi']);
ok('the boss shows this round\'s move and next round\'s (a round ahead), both from hit / brace / slam', in_array($cur, ['hit', 'brace', 'slam'], true) && in_array($next, ['hit', 'brace', 'slam'], true) && $cur !== $next);
$hp0 = (int)$R['fi']['foes'][0]['max'];
$tx(function (&$run, $u) { $run['fi']['foes'][0]['hp'] = (int)floor($run['fi']['foes'][0]['max'] * 0.3); trek_fight_round($run, $u, array_fill(0, count($run['party']), ['a' => 'guard'])); foreach ($run['party'] as $k => $p) $run['party'][$k]['hp'] = 99999; return [true, '']; }, true, 3);
$R = $run(3);
ok('under 35% his shell cracks (he takes more, and his moves change to hit / slam)', !empty($R['fi']['meta']['crack']) && !in_array('brace', [trek_boss_moves($R['fi'])[0], trek_boss_moves($R['fi'])[1]], true));
$xp0 = $mainXp();
$tx(function (&$run, $u) { for ($i = 0; $i < 40 && $run['fi']; $i++) { $run['fi']['foes'][0]['hp'] = 1; foreach ($run['party'] as $k => $p) $run['party'][$k]['hp'] = 99999; trek_fight_round($run, $u, array_fill(0, count($run['party']), ['a' => 'attack', 't' => 0])); } return [true, '']; }, true, 3);
$R = $run(3);
ok('Old Gneiss falls: flag set, fight over, chapter NOT complete (no finish row in III-a)', !$R['fi'] && $flag('gneiss_down') && !trek_run_done($R), json_encode($R['fi']));
$ms = q_one('SELECT * FROM trek_ms WHERE user_id = ? AND ms_key = ?', [$uid, TREK_KEY . ':ch3_gneiss']);
ok('ch3_gneiss paid once (max 1100 XP)', $ms && (int)$ms['xp'] > 0 && (int)$ms['xp'] <= 1100);
$at('stillgate');
$r = $tx(fn(&$run, $u) => trek_walk($run, $u, trek_spots(3)['stillgate']['x'], trek_spots(3)['stillgate']['y']), true, 3);
$at('gneiss');
$sg = trek_spots(3)['stillgate'];
$tx(function (&$run, $u) use ($sg) { $run['x'] = $sg['x'] - 1; $run['y'] = $sg['y']; return trek_walk($run, $u, $sg['x'], $sg['y']); }, true, 3);
ok('bumping the closed Still Gate pays ch3a_end once, and the gate stays shut (no finish row)', $flag('reached_stillgate') && (int)q_val('SELECT COUNT(*) FROM trek_ms WHERE user_id = ? AND ms_key = ?', [$uid, TREK_KEY . ':ch3a_end']) === 1 && !trek_run_done($run(3)));
exit($fails ? 1 : 0);
